package devcheck

// DefaultRules returns a fresh registry. Add each new built-in feature's rule
// here: the CLI, browser, strict exit policy and exceptions use it automatically.
// Severity depends on detection confidence; the purpose states the benefit.
func DefaultRules() []Rule {
	return []Rule{
		{ID: "asset-url", Severity: Violation, Extensions: []string{".html", ".templ"}, Purpose: "Use Gantry's asset pipeline for cache invalidation, compression and reusable assets", Guidance: "local script or stylesheet uses a literal URL; use assets.Path/Styles/ImportMap so deployments replace cached copies; document an intentional alternative", Check: checkAssetURLs},
		{ID: "form-scope", Severity: Advice, Extensions: []string{".js"}, Purpose: "Reuse form-scoped behavior safely as shared navigation evolves", Guidance: "document.querySelector('form') can select a navigation form; use a form ID or a Stimulus controller scoped to that form", Check: checkForms},
		{ID: "shared-layout", Severity: Advice, Extensions: []string{".html", ".templ"}, Purpose: "Keep asset loading and page enhancements in the shared layout", Guidance: "standalone page shell outside app/shared; prefer the shared layout so navigation, assets and development diagnostics stay consistent", Check: checkLayout},
		{ID: "raw-assets", Severity: Advice, Extensions: []string{".go"}, Purpose: "Avoid rebuilding asset serving outside Gantry's optimized pipeline", Guidance: "raw file server bypasses Gantry asset handling; use assets.Routes for scripts/styles, or document this route's separate purpose", Check: checkRawAssets},
		{ID: "development-guard", Severity: Violation, Extensions: []string{".go"}, Purpose: "Keep development-only middleware (source scans, timing, reload) out of production", Guidance: developmentGuardGuidance(), Check: checkDevelopmentGuard},
		{ID: "environment-default", Severity: Violation, Extensions: []string{".go"}, Purpose: "Use Gantry's production defaults unless development is explicitly selected", Guidance: "GANTRY_ENV should default to production; opt into development explicitly", Check: checkEnvironment},
		{ID: "import-boundary", Severity: Violation, Extensions: []string{".go", ".templ"}, Purpose: "Keep the app's layers one way (routes.go → resources → services → models, and app/shared for all but models, which import no other app package) so each package is reusable and testable alone", Guidance: "app/models imports no web, templ or other app package; app/services no web or resource; app/shared no resource; a nested resource not its parent; nothing under app/ imports the routes package", Check: checkImportBoundary},
		{ID: "view-db", Severity: Violation, Extensions: []string{".templ"}, Purpose: "Keep pages cacheable and testable without a database: controllers load, views draw", Guidance: "a view uses models.New, models.Queries, db.DB or a DB's Read/Write pool; load the data in the controller's action and pass plain values to the component", Check: checkViewDB},
		{ID: "raw-html", Severity: Violation, Extensions: []string{".go", ".templ"}, Purpose: "Keep templ's escaping, which stops a visitor's text running as the page's HTML or script", Guidance: "templ.Raw and templ.JSUnsafeFuncCall skip escaping; write { value } (templ.URL for links), or document the escaping with an exception", Check: checkRawHTML},
		{ID: "env-outside-config", Severity: Violation, Extensions: []string{".go"}, Purpose: "Read the environment once, in config, so it's checked at start and tests set it as a value", Guidance: "os.Getenv in app/; add a field to config.Config and give it to what needs it", Check: checkEnvOutsideConfig},
		{ID: "background-work", Severity: Violation, Extensions: []string{".go"}, Purpose: "Use jobs for work after the response, so a deploy or a crash doesn't lose it and failures are retried", Guidance: "a go statement, time.Sleep or time.AfterFunc in app/; enqueue a job (EnqueueIn, EnqueueAt), broadcast with live, or use sync.WaitGroup.Go for work the request waits for", Check: checkBackgroundWork},
		{ID: "http-client", Severity: Violation, Extensions: []string{".go"}, Purpose: "Bound every outbound request, so a slow server can't hold requests and jobs forever", Guidance: "http.DefaultClient, http.Get, Head, Post and PostForm have no timeout; send with an &http.Client{Timeout: ...} of your own", Check: checkHTTPClient},
		{ID: "sql-outside-models", Severity: Violation, Extensions: []string{".go"}, Purpose: "Keep SQL in app/models, where sqlc checks it against the schema", Guidance: "raw SQL or a *sql.DB in app/ outside app/models; write the query in app/models/<table>.sql and call models.New(c.DB.Read).Name(ctx), or models.New(tx) in c.DB.Tx", Check: checkSQLOutsideModels},
		{ID: "cross-origin-bypass", Severity: Violation, Extensions: []string{".go"}, Purpose: "Keep cross-site request protection on every state-changing route but the callbacks that prove themselves", Guidance: "web.CrossOrigin's bypass patterns exempt every method and request they match; route the one callback with rt.CrossOriginCallback(\"POST /path\", h), and have it check its own proof (OAuth state, a signature)", Check: checkCrossOriginBypass},
		{ID: "tx-defer", Severity: Violation, Extensions: []string{".go"}, Purpose: "Never leave a transaction open, holding its connection (on SQLite, the one writer)", Guidance: "a transaction is begun and committed with no deferred Rollback, so an early return or a panic leaves it open; defer tx.Rollback() right after Begin (it does nothing once committed), or use db.DB.Tx", Check: checkTxDefer},
		{ID: "read-then-write", Severity: Advice, Extensions: []string{".go"}, Purpose: "Save edits without losing one made meanwhile", Guidance: "a Get on the Read pool, then an Update or Delete on the Write pool, in one function; read and write in one c.DB.Tx with models.New(tx)", Check: checkReadThenWrite},
		{ID: "get-mutates", Severity: Advice, Extensions: []string{".go"}, Purpose: "Keep GETs safe to repeat, as prefetching browsers and crawlers assume", Guidance: "a GET handler (Index, Show, New, Edit, or a GET route's function) writes to the database; route it as POST and send it from a button in a form", Check: checkGetMutates},
		{ID: "inline-download", Severity: Advice, Extensions: []string{".go"}, Purpose: "Send uploads as downloads, so an uploaded HTML or SVG file can't run as the app's own page", Guidance: "http.ServeContent or ServeFile with no Content-Disposition serves a file inline; send uploads with web.Download or storage's routes, and serve inline only types checked to be images", Check: checkInlineDownload},
		{ID: "cached-scope", Severity: Violation, Extensions: []string{".go"}, Purpose: "Cache only pages that are the same for every visitor, so no one is shown a page drawn for someone else", Guidance: "a route the page cache serves (Cached, PageCache.Handler, or Resources wrapped in the cache's Handler) has a handler that reads auth.Current, SignedIn, a cookie or the flash; draw that part where it isn't cached, or add the route with Handle", Check: checkCachedScope},
		{ID: "cache-set-cookie", Severity: Violation, Extensions: []string{".go"}, Purpose: "Set cookies and sessions on routes whose handler runs for every visitor", Guidance: "a route the page cache serves has a handler that sets a cookie, the flash or a session, which a cached copy never sends; set it on a route added with Handle", Check: checkCacheSetCookie},
		{ID: "migration-down", Severity: Violation, Extensions: []string{".sql"}, Purpose: "Keep rollback and testkit.Migrations checking every migration's undo", Guidance: "migration has no -- +goose Down section, so rolling back stops at it; add one that undoes the up, or leave it empty to mark the migration irreversible", Check: checkMigrationDown},
	}
}
